import{_ as t,o as s,c as r,a4 as i}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse('{"title":"ADR-0048 — Le site du projet est généré depuis le dépôt","description":"Extrait de docs/adr/0048-site-du-projet-genere-depuis-le-depot.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0048 — Le site du projet est généré depuis le dépôt","description":"Extrait de docs/adr/0048-site-du-projet-genere-depuis-le-depot.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0048-site-du-projet-genere-depuis-le-depot.md","filePath":"developpeurs/adr/0048-site-du-projet-genere-depuis-le-depot.md"}'),n={name:"developpeurs/adr/0048-site-du-projet-genere-depuis-le-depot.md"};function a(o,e,d,l,u,c){return s(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0048--le-site-du-projet-est-généré-depuis-le-dépôt" tabindex="-1">ADR-0048 — Le site du projet est généré depuis le dépôt <a class="header-anchor" href="#adr-0048--le-site-du-projet-est-généré-depuis-le-dépôt" aria-label="Permalink to &quot;ADR-0048 — Le site du projet est généré depuis le dépôt {#adr-0048--le-site-du-projet-est-généré-depuis-le-dépôt}&quot;">​</a></h1><p><strong>Date :</strong> 24 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> plan de déploiement du 24/09/2026, décisions D7, D8 et D9 ; s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0045-deploiement-par-un-exploitant-non-developpeur">ADR-0045</a> (installateur) et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0046-profils-d-usage-a-l-installation">ADR-0046</a> (profils)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Teuthis n&#39;a pas de site. Sa documentation n&#39;existe qu&#39;en Markdown, dans <code>docs/</code> et dans le README, lisible sur GitHub par qui sait l&#39;y chercher.</p><p>Le Product Owner prend drupal.org comme modèle : un site qui présente le CMS, explique comment l&#39;installer et donne accès à sa documentation. Avec les profils (ADR-0046), l&#39;installation dépend de l&#39;usage. Le site doit donc aussi aider à choisir son profil et donner la commande qui va avec.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Le site est un site statique généré par la CI à partir de ce dépôt, avec VitePress (D8).</strong> VitePress utilise Vue et Markdown, comme le reste du dépôt. Il fait la recherche localement, sans service tiers, et versionne la documentation. Le site est reconstruit <strong>à chaque étiquette de version</strong>, et la documentation de chaque version reste consultable.</p><p><strong>2. Six rubriques.</strong></p><ul><li><strong>Accueil</strong> : une entrée par usage, avec des captures du site obtenu et ce qu&#39;il ne fait pas.</li><li><strong>Installer</strong> : un sélecteur d&#39;usage qui affiche la commande correspondante, les prérequis et le guide pas à pas.</li><li><strong>Documentation</strong> : la notice découpée en pages, un guide par profil, et le guide du référent (sauvegarde, mise à jour, dépannage).</li><li><strong>Extensions</strong> : le catalogue, <strong>généré à partir des manifestes et des profils</strong>.</li><li><strong>Développeurs</strong> : la référence de l&#39;API, <strong>générée à partir de l&#39;OpenAPI de FastAPI</strong>, le SDK, les ADR et un guide de contribution.</li><li><strong>Versions</strong> : les notes de version et les signatures des images.</li></ul><p>Tout ce qui décrit le code est <strong>généré à partir du code</strong> : le site ne peut pas dériver du dépôt.</p><p><strong>3. Le site est publié sur GitHub Pages, à l&#39;adresse fournie par GitHub, puis branché sur un domaine propre au projet quand il est prêt (D7).</strong></p><ul><li>L&#39;installateur et sa somme de contrôle sont servis par le site, et copiés dans chaque release.</li><li><strong>Acheter le domaine et publier le site sont des actes sortants, faits par le Product Owner.</strong></li></ul><p><strong>4. En français seulement en v1 (D9).</strong> Le marché premier est français : collectivités, RGAA, FranceConnect. L&#39;anglais viendra quand un premier utilisateur hors de France se présentera. VitePress le permet sans refonte.</p><p><strong>5. Le site du projet est lui-même accessible.</strong> Il vise le RGAA AA, avec axe en CI. Il n&#39;a aucun traceur, donc aucun bandeau cookies.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td>Un site construit avec Teuthis lui-même</td><td>Une belle preuve par l&#39;usage, mais il faut d&#39;abord le front (ADR-0047), et la documentation deviendrait du contenu à ressaisir et à synchroniser avec le code. À reconsidérer quand le thème Blog existera.</td></tr><tr><td>Nuxt Content</td><td>Même écosystème que l&#39;admin, mais plus lourd pour de la documentation : versions et recherche seraient à monter soi-même.</td></tr><tr><td>MkDocs Material</td><td>Excellent pour la documentation pure, mais écrit en Python et Jinja, sans lien avec la pile Vue du projet.</td></tr><tr><td>Acheter le domaine dès maintenant</td><td>La commande affichée ne changerait jamais d&#39;adresse. Mais cela bloque la mise en ligne sur un achat, quand GitHub Pages permet de brancher le domaine ensuite sans rien casser.</td></tr><tr><td>Français et anglais dès la v1</td><td>Toute la documentation à traduire, puis à tenir à jour deux fois à chaque version, avant d&#39;avoir un seul utilisateur anglophone.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>La documentation suit le code, version par version.</li><li>Le catalogue et la référence de l&#39;API sont toujours exacts, puisqu&#39;ils sont générés.</li></ul><p><strong>Négatives</strong></p><ul><li><code>docs/notice-utilisateur.md</code> devra être découpée en pages. Il faudra aussi décider ce qui reste dans le README.</li><li>Tant que le domaine n&#39;est pas branché, la commande d&#39;installation affichée change une fois d&#39;adresse.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Squelette VitePress, notice découpée en pages, guide du référent, publication par la CI à chaque étiquette, avec documentation versionnée. <strong>Fait en partie le 07/10/2026</strong> (lot 13, issue #7). Fait : squelette VitePress dans <code>site/</code>, notice et guide du référent découpés à la construction (<code>site/scripts/generer/documents.mjs</code>, une page par <code>##</code>, liens <code>#ancre</code> réécrits), job <code>site</code> de <code>ci.yml</code> (construction, axe, liens), job <code>site</code> de <code>publication-images.yml</code> (reconstruction à chaque étiquette, poussée sur <code>gh-pages</code>). <strong>Reste</strong> : la documentation versionnée, remplacée par une seule documentation, celle de la dernière version (<a href="/teuthis-cms-distribution/developpeurs/adr/0067-site-du-projet-heberge-dans-le-depot-de-distribution">ADR-0067</a>), et la première publication réelle du job, jamais exécuté de bout en bout (case suivante de l&#39;ADR-0067).</li><li>[ ] Rubriques Installer (sélecteur d&#39;usage), Extensions (générée à partir des manifestes et des profils) et Développeurs (OpenAPI, SDK, ADR). <em>Avancement au 07/10/2026 (lot 13) : Installer (sélecteur de profil) et Développeurs (OpenAPI générée, ADR, contribution) sont faits ; restent Extensions et le SDK.</em></li><li>[ ] Mise en ligne sur GitHub Pages, puis branchement du domaine acheté par le Product Owner ; axe en CI. <em>Avancement au 07/10/2026 (lot 13) : axe en CI est fait (job <code>site</code> de <code>ci.yml</code>) ; restent la mise en ligne, geste du Product Owner (<a href="/teuthis-cms-distribution/developpeurs/adr/0067-site-du-projet-heberge-dans-le-depot-de-distribution">ADR-0067</a>), et le domaine.</em> <strong>Mise en ligne faite le 08/10/2026</strong> (ADR-0067) : <a href="https://bastien-oc20.github.io/teuthis-cms-distribution/" target="_blank" rel="noreferrer">https://bastien-oc20.github.io/teuthis-cms-distribution/</a>, axe en CI (job <code>site</code>). Reste le domaine propre, acheté par le Product Owner.</li></ul>',23)])])}const m=t(n,[["render",a]]);export{g as __pageData,m as default};
